"use client";

import { useEffect, useMemo, useRef, type ReactNode } from "react";
import {
  DataGridProvider,
  DataGridRoot,
  DataGridHeader,
  DataGridBody,
  defineColumns,
} from "@/registry/default/components/data-grid/data-grid";
import {
  useDataGridPresence,
  type PresenceHighlightEntry,
} from "@/registry/default/components/data-grid-presence/data-grid-presence";
import { generateDemoRows, type DemoRow } from "./demo-data";

const columns = defineColumns<DemoRow>()([
  { id: "name", header: "Name", accessorKey: "name", type: "text", width: 85, flex: 1 },
  { id: "email", header: "Email", accessorKey: "email", type: "text", width: 100, flex: 2 },
  { id: "age", header: "Age", accessorKey: "age", type: "number", width: 55, flex: 1 },
  { id: "role", header: "Role", accessorKey: "role", type: "text", width: 70, flex: 1 },
  { id: "score", header: "Score", accessorKey: "score", type: "number", width: 55, flex: 1 },
] as const);

const ROW_COUNT = 24;
const COL_COUNT = columns.length;

/** Fixed simulated users — stable id/name/color; the last has no valid color and paints with the primary fallback, matching the real transport's `PresenceHighlight.id` contract. */
const SIMULATED_USERS: { id: string; name: string; color: string }[] = [
  { id: "ada", name: "Ada", color: "var(--chart-2)" },
  { id: "grace", name: "Grace", color: "var(--chart-3)" },
  { id: "linus", name: "Linus", color: "var(--chart-5)" },
  { id: "guest", name: "No valid color", color: "not-a-color" },
];

/** Deterministic pseudo-random walk so the demo is reproducible across renders (no Math.random). */
function nextWalkStep(current: number, max: number, seed: number): number {
  const delta = ((seed % 5) - 2) as number; // -2..2
  return Math.max(0, Math.min(max, current + delta));
}

/**
 * Drives the 4 simulated users' selections on a timer, calling the real (imperative) mechanism
 * `setPresenceHighlights` directly — exactly what a websocket/CRDT handler would do on each remote
 * update. Ada and Grace use the view-index `range` form; Linus uses the rowId-native RANGE form
 * `{ rowIds, columnIds }` (a real peer would send this after a local sort or filter), so his
 * highlight keeps tracking the same rows even as `headerClickBehavior="sort"` reorders the view
 * underneath it. If a local filter or hidden column splits his range, it paints one rect — and
 * one chip — per surviving contiguous fragment instead of one wrong rect. Renders nothing itself.
 */
function useSimulatedPresenceDriver(rows: readonly DemoRow[], setPresenceHighlights: (highlights: PresenceHighlightEntry[]) => void): void {
  const tickRef = useRef(0);

  useEffect(() => {
    const positions = SIMULATED_USERS.slice(0, 2).map((_, i) => ({ row: (i * 7) % ROW_COUNT, col: i % COL_COUNT }));
    const linusAnchor = Math.floor(ROW_COUNT / 2);
    const linusRowIds = [rows[linusAnchor]?.id, rows[linusAnchor + 1]?.id].filter((id): id is string => id !== undefined);
    const linusColumnIds = [columns[COL_COUNT - 1]!.id, columns[COL_COUNT - 2]!.id];

    const interval = setInterval(() => {
      tickRef.current += 1;
      const tick = tickRef.current;

      // Ada (index 0) periodically selects a 2-row range overlapping Grace's cell — shows blend
      // legibility when two highlights cover the same cell.
      const overlapTick = tick % 6 === 0;

      const rangeHighlights: PresenceHighlightEntry[] = SIMULATED_USERS.slice(0, 2).map((user, i) => {
        // positions has one entry per SIMULATED_USERS.slice(0, 2) index, so i is always in-bounds
        const pos = positions[i]!;
        pos.row = nextWalkStep(pos.row, ROW_COUNT - 1, tick * (i + 3) + i);
        pos.col = nextWalkStep(pos.col, COL_COUNT - 1, tick * (i + 5) + i);

        const range =
          i === 0 && overlapTick
            ? { x: positions[1]!.col, y: positions[1]!.row, width: 1, height: 2 } // SIMULATED_USERS has 4 fixed entries
            : { x: pos.col, y: pos.row, width: 1, height: 1 };

        return { id: user.id, color: user.color, range, label: user.name };
      });

      const linus = SIMULATED_USERS[2]!; // SIMULATED_USERS has 4 fixed entries
      const linusHighlight: PresenceHighlightEntry = {
        id: linus.id,
        color: linus.color,
        rowIds: linusRowIds,
        columnIds: linusColumnIds,
        label: linus.name,
      };

      const guest = SIMULATED_USERS[3]!;
      const guestHighlight: PresenceHighlightEntry = {
        id: guest.id,
        color: guest.color,
        rowId: rows[ROW_COUNT - 2]!.id,
        columnId: columns[0]!.id,
        label: guest.name,
      };

      setPresenceHighlights([...rangeHighlights, linusHighlight, guestHighlight]);
    }, 900);

    return () => clearInterval(interval);
  }, [rows, setPresenceHighlights]);
}

/**
 * Multiplayer presence highlights (docs/multiplayer-presence): 4 simulated users move their
 * cell/range selections on a timer via `setPresenceHighlights` — the same imperative mechanism a
 * real websocket/CRDT handler would call. Zero core re-renders: only the plugin's own overlay
 * subscribes to this state (see the render-count probe in data-grid-presence.test.tsx). Click a
 * header to sort (`headerClickBehavior="sort"`) and watch Linus's highlight — sent as a
 * rowId-native `{ rowIds, columnIds }` range entry — keep following the same rows instead of a
 * fixed view position.
 */
export default function DataGridPresenceDemo(): ReactNode {
  const rows = useMemo(() => generateDemoRows(ROW_COUNT), []);
  const { plugin, setPresenceHighlights } = useDataGridPresence();
  const plugins = useMemo(() => [plugin], [plugin]);
  useSimulatedPresenceDriver(rows, setPresenceHighlights);

  return (
    <div className="w-full flex h-[420px] flex-col gap-2">
      <p className="text-sm text-muted-foreground">
        Click a header to sort: Ada's and Grace's highlights are fixed to view positions and jump
        around, but Linus's 2×2 range is tied to its row ids and keeps following the same rows —
        a local filter that splits the range paints one labeled rect per fragment.
      </p>
      <div className="min-h-0 flex-1 overflow-hidden rounded-md border border-border">
        <DataGridProvider
          defaultData={rows}
          columns={columns}
          plugins={plugins}
          headerClickBehavior="sort"
        >
          <DataGridRoot className="h-full rounded-none border-none">
            <DataGridHeader />
            <DataGridBody />
          </DataGridRoot>
        </DataGridProvider>
      </div>
    </div>
  );
}

/** Deterministic LCG so SSR/CSR markup match without Math.random(); shared across example rows. */
function createSeededLcg(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1103515245 + 12345) & 0x7fffffff;
    return state / 0x7fffffff;
  };
}

export type DemoRow = {
  id: string;
  name: string;
  email: string;
  age: number;
  active: boolean;
  role: string;
  joined: string;
  score: number;
};

const ROLES = ["Admin", "User", "Editor", "Viewer", "Manager"] as const;
const ADJECTIVES = ["Eager", "Quick", "Silent", "Bold", "Swift"] as const;
const NOUNS = ["Eagle", "Lion", "Tiger", "Bear", "Wolf"] as const;

/** Generates `count` deterministic demo rows for example previews (seed 42, stable across renders). */
export function generateDemoRows(count: number, seed = 42): DemoRow[] {
  const next = createSeededLcg(seed);
  const rows: DemoRow[] = [];
  for (let i = 0; i < count; i++) {
    rows.push({
      id: `row-${i}`,
      name: `${ADJECTIVES[Math.floor(next() * ADJECTIVES.length)]} ${NOUNS[Math.floor(next() * NOUNS.length)]}`,
      email: `user${i}@example.com`,
      age: Math.floor(next() * 50) + 18,
      active: next() > 0.5,
      role: ROLES[Math.floor(next() * ROLES.length)]!, // ROLES is a fixed non-empty literal array
      joined: `${2020 + Math.floor(next() * 5)}-${String(Math.floor(next() * 12) + 1).padStart(2, "0")}-${String(Math.floor(next() * 28) + 1).padStart(2, "0")}`,
      score: Math.floor(next() * 100),
    });
  }
  return rows;
}
